def canonical_sha(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()

def validate_headless_fixture(fixture, allowed=HEADLESS_ITEMS):
    # Source/input domain admission, not a claim that every layout is native-validated.
    # Full geometric/default scalar checks are retained in engine.validate_fixture.
    if (type(fixture) is not dict or type(fixture.get('sides')) is not list or len(fixture['sides']) != 2
            or fixture.get('rules') != 'default'):
        raise ValueError('default two-sided headless fixture required')
    for side in fixture['sides']:
        if (type(side.get('character_class')) is not int or side['character_class'] not in (0, 2)
                or type(side.get('items')) is not list):
            raise ValueError('source Ranger/Berserker default domain required')
        for item in side['items']:
            if type(item.get('item_index')) is not int or item['item_index'] not in allowed:
                raise ValueError('item outside185 headless battle family')
    return True


