def observer_label(data):
    if data.get('profile_id') == CAPTURED_JOINT_PROFILE:return 'observer7-king-basic-A-captured-candidate471'
    if data.get('profile_id') == PURE441_PROFILE:return 'observer7-390-fixed441-pure-candidate443'
