    if data.get('profile_id') == MANA_PAIR_PROFILE:return 'observer7-233-headless-mana-pair-battle'
    if data.get('profile_id') == CARROT_BURNING_PROFILE:return 'observer7-228-headless-carrot-burning-battle'
    if data.get('profile_id') == START_COLLAR_PROFILE:return 'observer7-223-headless-start-collar-battle'
    if data.get('profile_id') == EXISTING_WEAPON_PROFILE:return 'observer7-218-headless-existing-weapon-battle'
    if data.get('profile_id') == POTION_PROFILE:return 'observer7-214-headless-potion-battle'
