def validate_captured_joint_fixture(fixture):
    if type(fixture) is not dict or canonical_sha(fixture) != CAPTURED_JOINT_FIXTURE_SHA256:
        raise ValueError('captured joint outside fixed26 Source fixture')
    if any(type(side['character_class']) is not int or side['character_class'] != 0 for side in fixture['sides']):
        raise ValueError('captured joint class0 only')
    items = {item['instance_id']: item for side in fixture['sides'] for item in side['items']}
    expected = {f'P:{n}' for n in range(14)} | {f'O:{n}' for n in range(12)}
    if (len(items) != 26 or set(items) != expected or items['P:6']['item_index'] != 262
            or items['P:7']['item_index'] != 23 or items['P:12']['item_index'] != 1 or items['O:9']['item_index'] != 19):
        raise ValueError('captured joint exact26 subtype identities')
    return True


def validate_captured_joint_profile(data, fixture):
    validate_captured_joint_fixture(fixture)
    if (data.get('schema') != CAPTURED_JOINT_SCHEMA or data.get('profile_id') != CAPTURED_JOINT_PROFILE
            or data.get('mode') != 'genuine' or data.get('terminal_profile') != SINGLE_KING_TERMINAL):
        raise ValueError('captured joint exact14 ABI/profile/terminal required')
    return True
